SELECT COALESCE(MAX(display_order), -1) + 1
FROM user_cards
WHERE user_id = #{userId}

SELECT user_card_id, card_id
FROM user_cards
WHERE codef_account_credential_id = #{linkId}
  AND user_id = #{userId}
ORDER BY display_order ASC, user_card_id ASC

SELECT user_card_id, codef_card_key_hash
FROM user_cards
WHERE codef_account_credential_id = #{linkId}
  AND user_id = #{userId}

SELECT user_card_id
FROM user_cards
WHERE user_id = #{userId}
  AND codef_card_key_hash = #{codefCardKeyHash}

